function nativeShell(host){const result={};for(const d of nativeParts){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(d.positions),3));g.setAttribute('normal',new THREE.BufferAttribute(new Float32Array(d.normals),3));g.setAttribute('sourceFaceIndex',new THREE.BufferAttribute(new Uint32Array(d.sourceFaceIndex),1));g.setAttribute('sourceAttributeWord',new THREE.BufferAttribute(new Uint16Array(d.sourceAttributeWord),1));g.setIndex(new THREE.BufferAttribute(new Uint16Array(d.indices),1));const o=new THREE.Mesh(g,plastic(0x8b8e8b));o.name='C008 own native '+d.id+' complete half';o.position.fromArray(d.translation);o.userData={source:'official-structure',sourceFaceCount:d.triangles};host.body.add(o);result[d.id]=o;}return result;}
function mainBoard(host){const shape=hole(roundedRect(20.4,21.2,.5),0,0,1.8),holes=[];for(const h of spec.headers)for(let i=0;i<h.count;i++){const y=h.position[1]+((h.count-1)/2-i)*2.54;hole(shape,h.position[0],y,.27);holes.push([h.position[0],y]);}for(const x of[-3,-1,1,3])hole(shape,x,-5.6,.17);const pcb=solid(host.body,shape,.8,[0,0,-1.55],plastic(0x304b3d),'C008 own inferred main PCB with real mount and nine through-tail holes'),posts=[[-9,8],[9,8],[-9,-9],[9,-9]].map(([x,y])=>box(host.body,[1.2,1.2,2],[x,y,-2.55],plastic(0xa6aaa1),'C008 inferred PCB stand reaches original rear inner floor'));
 const module=box(host.body,[7,7,1.1],[6.3,5.3,-.2],plastic(0x323a34),'C008 retained ESP32-PICO-D4 package envelope'),lands=[];for(let edge=0;edge<4;edge++)for(let i=0;i<10;i++){const p=(i-4.5)*.6,xy=edge<2?[6.3+(edge?1:-1)*3.45,5.3+p]:[6.3+p,5.3+(edge===2?-1:1)*3.45];lands.push(box(host.body,[edge<2?.4:.24,edge<2?.24:.4,.07],[...xy,-.705],tin(),'C008 inferred retained QFN solder terminal'));}
 const passives=[];for(const[x,y]of[[-4,8],[-4,6],[-5,3],[3,-3],[5,-3],[7,-3],[-6,-3],[-8,8]]){passives.push(box(host.body,[1.1,.7,.55],[x,y,-.475],plastic(0x9e9a7f),'C008 supported passive envelope'));for(const s of[-1,1])passives.push(box(host.body,[.22,.75,.58],[x+s*.5,y,-.46],tin(),'C008 passive retained termination'));}
 const mountStop=cylinder(host.body,2,.25,[0,0,-.65],tin(),'C008 real retained blind M2 stop above original rear bore;depth inferred'),antenna=box(host.body,[14,2.1,1.1],[0,9.2,.0],plastic(0x202721),'C008 top-edge supported radio antenna envelope');return{pcb,posts,module,lands,passives,mountStop,antenna,holes};}
function usb(host){const frame=new THREE.Group();frame.position.fromArray(spec.usb.position);frame.quaternion.copy(FACE.bottom);frame.name='C008 actual USB-C receiver frame';host.body.add(frame);const shape=roundedRect(8.1,3.1,1.5);shape.holes.push(roundedRect(7.6,2.6,1.25));const shell=solid(frame,shape,6.8,[0,0,-6.8],tin(),'C008 USB-C true metal capsule wall;open mouth'),stop=box(frame,[8.1,3.1,.35],[0,0,-6.975],plastic(0x232a26),'C008 USB-C supported deep rear stop'),tongue=box(frame,[6.4,.5,5.4],[0,0,-3.7],plastic(0x263029),'C008 USB-C real dielectric tongue'),contacts=[];for(const sign of[-1,1])for(let i=0;i<6;i++)contacts.push(box(frame,[.28,.06,4.7],[(i-2.5)*.85,sign*.28,-3.65],gold(),'C008 USB-C independent retained contact'));
 const seat=box(host.body,[8.8,5.6,.9],[0,-8.3,.6],plastic(0x38453a),'C008 USB-C package seat supported on main PCB'),legs=[];for(const x of[-3.8,3.8])legs.push(box(host.body,[.35,5.5,1.9],[x,-8.4,.2],tin(),'C008 USB-C stamped retained leg onto PCB'));return{frame,shell,stop,tongue,contacts,seat,legs};}
function grove(host){const frame=new THREE.Group();frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);frame.name='C008 actual PH-photo fourpin receiver';host.body.add(frame);const white=plastic(0xd3c5a5),floor=box(frame,[10.2,.55,6.4],[0,-2.325,-3.2],white,'C008 Grove receiving floor'),stop=box(frame,[10.2,4.65,.55],[0,-.275,-6.125],white,'C008 Grove real deep backstop'),walls=[-1,1].map(sign=>box(frame,[.65,5.2,6.4],[sign*4.775,0,-3.2],white,'C008 Grove true sidewall')),bridge=box(frame,[4.6,.55,3],[0,1.9,-4.9],white,'C008 Grove partial top latch bridge'),guides=[-1,1].map(sign=>box(frame,[.7,.65,1.5],[sign*4.1,1.9,-.75],white,'C008 Grove retained mouth guide')),contacts=[],returns=[],tails=[],pads=[],barrels=[];
 for(const x of[-3,-1,1,3]){contacts.push(box(frame,[.32,.32,5.9],[x,-.2,-3.45],tin(),'C008 Grove independent actual contact'));returns.push(box(host.body,[.32,.8,1.6],[x,-5.6,-1.55],tin(),'C008 Grove actual retained return onto main PCB'));tails.push(cylinder(host.body,.14,.8,[x,-5.6,-1.15],tin(),'C008 Grove retained PCB tail'));barrels.push(ring(host.body,.17,.145,.8,[x,-5.6,-1.55],tin(),'C008 Grove actual plated tail bore wall'));pads.push(ring(host.body,.42,.17,.035,[x,-5.6,-.75],gold(),'C008 Grove supporting PCB land'));}
 return{frame,floor,stop,walls,bridge,guides,contacts,returns,tails,pads,barrels};}
function headers(host){const result={};for(const h of spec.headers){const shape=roundedRect(2.6,h.count*2.54,.15),centres=[];for(let i=0;i<h.count;i++){const y=((h.count-1)/2-i)*2.54;rectHole(shape,0,y,1.1,1.1);centres.push([h.position[0],h.position[1]+y]);}const housing=solid(host.body,shape,3,[h.position[0],h.position[1],-4.75],plastic(0x161d18),'C008 '+h.id+' actual housing with separate square receiving wells'),stops=[],contacts=[],tails=[],lands=[],barrels=[];
  for(const[x,y]of centres){stops.push(box(host.body,[1.12,1.12,.2],[x,y,-1.65],plastic(0x202820),'C008 header true deep socket stop'));for(const[dx,dy,sx,sy]of[[.47,0,.12,.68],[-.47,0,.12,.68],[0,.47,.68,.12],[0,-.47,.68,.12]])contacts.push(box(host.body,[sx,sy,1.85],[x+dx,y+dy,-2.6],gold(),'C008 header retained spring-contact wall'));tails.push(cylinder(host.body,.14,.8,[x,y,-1.15],gold(),'C008 header actual tail through board hole'));barrels.push(ring(host.body,.27,.17,.8,[x,y,-1.55],gold(),'C008 header plated actual board bore wall'));for(const z of[-1.565,-.75])lands.push(ring(host.body,.39,.27,.025,[x,y,z],gold(),'C008 header plated annular supporting land'));}
  result[h.id]={housing,stops,contacts,tails,lands,barrels,centres};
 }return result;}
function opticalAndKeys(host){const pcb=box(host.body,[4.2,4.2,.3],[0,0,1.05],plastic(0x344e3e),'C008 supported single RGB subboard'),risers=[-1,1].map(x=>box(host.body,[.6,2.4,1.65],[x*1.7,0,.075],tin(),'C008 RGB subboard supporting retained riser from PCB')),rgbPackage=box(host.body,[3.5,3.5,1.4],[0,0,1.9],plastic(0xc8d0c2),'C008 actual single SK6812 3535 package'),rgbLeads=[];for(const sign of[-1,1])for(const y of[-1,1])rgbLeads.push(box(host.body,[.42,.7,.18],[sign*1.6,y,1.24],tin(),'C008 RGB package retained terminal'));
 const irBoard=box(host.body,[2.3,3.3,.3],[-7.45,9.6,1.1],plastic(0x314d3c),'C008 own IR local supported PCB'),irStem=box(host.body,[1.9,2.5,1.65],[-7.45,9.6,.125],plastic(0x696e62),'C008 IR board retained pedestal'),irPackage=box(host.body,[1.8,2.6,.7],[-7.45,9.6,1.6],plastic(0xaeb1a1),'C008 passive IR ceramic package'),irLens=box(host.body,[1.5,1.4,.8],[-7.45,10.2,2.35],materials.glossy(0x171e1d,{roughness:.3}),'C008 own passive infrared resin optic;no visible emitter API'),irLeads=[-1,1].map(sign=>box(host.body,[.25,2,.2],[-7.45+sign*.9,9.5,1.3],tin(),'C008 retained IR lead'));
 const mainShape=hole(roundedRect(3.5,3.5,.2),0,0,.55),mainSwitch=solid(host.body,mainShape,.65,[0,4,2.65],plastic(0x727767),'C008 main tactile package real plunger receiving bore'),mainStand=box(host.body,[3.5,3.5,3.4],[0,4,.95],plastic(0x394b3e),'C008 actual main switch retained support from PCB to cap'),mainStem=cylinder(host.body,.45,.6,[0,4,3.55],tin(),'C008 main key actual movable retained switch plunger'),resetSwitch=(()=>{const s=rectHole(roundedRect(3.2,2.3,.15),0,0,1.4,1.4),o=solid(host.body,s,1.2,[-8.6,5,2.2],plastic(0x6d7167),'C008 reset tactile package real receiving bore');o.quaternion.copy(FACE.left);return o;})(),resetStand=box(host.body,[2.4,3.2,1.8],[-9.2,5,.15],plastic(0x414d42),'C008 reset package pedestal from PCB to receiving housing'),resetStem=box(host.body,[.65,1.2,1.2],[-10.1,5,2.2],tin(),'C008 reset actual movable contact plunger');
 return{pcb,risers,rgbPackage,rgbLeads,irBoard,irStem,irPackage,irLens,irLeads,mainSwitch,mainStand,mainStem,resetSwitch,resetStand,resetStem};}
function films(host){const b=spec.labels.bottom,c=spec.labels.compliance,shape=hole(roundedRect(...b.size,.05),0,-2.8,b.holeRadius),bottom=solid(host.body,shape,.04,[0,2.8,-4.59],plastic(0xd5d8cb),'C008 real rear label film on original native recessed floor;M2 stays open'),compliance=solid(host.body,roundedRect(...c.size,.05),.04,[0,0,0],plastic(0xd9dbd3),'C008 real compliance film on fixed original side land');compliance.position.fromArray(c.position);compliance.quaternion.copy(FACE.top);for(const o of[bottom,compliance])o.userData={role:'physical-label-substrate',registrationInferred:true};return{bottom,compliance};}
